function cue(kind,amp=1,pan=0){try{foley?.play(kind,amp,pan);}catch{}}function tone(freq=150,dur=.24,amp=.13){if(!ac)return;const osc=ac.createOscillator(),g=ac.createGain(),t=ac.currentTime;osc.type='sine';osc.frequency.value=freq;g.gain.setValueAtTime(amp,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);osc.connect(g).connect(master);osc.start(t);osc.stop(t+dur);}function save(silent=false){try{if(!Q.validate(s,C,E))throw Error('Estado no válido');const raw=JSON.stringify(s),old=localStorage.getItem(Q.KEY);if(old&&old!==raw){try{if(Q.validate(Q.migrate(JSON.parse(old)),C,E))localStorage.setItem(Q.KEY+'-backup',old);}catch{}}localStorage.setItem(Q.KEY,raw);if(!silent)toast('Partida guardada');return true;}catch{if(!silent)toast('No se pudo guardar. Comprueba el almacenamiento del navegador.');return false;}}function load(){for(const key of [Q.KEY,Q.KEY+'-backup']){try{const data=Q.migrate(JSON.parse(localStorage.getItem(key)));if(Q.validate(data,C,E))return data;}catch{}}return null;}
